function draftAttributes(){return `data-request-id="${crypto.randomUUID()}" data-targets="${esc(JSON.stringify(list(projection.targets)))}" data-policies="${esc(JSON.stringify(list(projection.policies)))}"`}
function policyChoices(selected=[],policies=list(projection.policies)){const rows=policies.map(p=>`<div class="actions"><label class="choice"><input type="checkbox" name="policy_id" value="${esc(p.id)}" ${selected.includes(p.id)?'checked':''}><span><b>${esc(p.name||p.id)}</b><small>${esc(p.service_id)} · ${esc(p.action)}</small></span></label>${canOperate('policy.put')?`<button type="button" data-copy-policy="${esc(p.id)}">Copy for this device</button>`:''}</div>`);for(const id of selected.filter(id=>!policies.some(p=>p.id===id)))rows.push(`<label class="choice"><input type="checkbox" name="policy_id" value="${esc(id)}" checked><span><b>${esc(id)}</b><small>Unavailable reference retained. Remove it explicitly to change the assignment.</small></span></label>`);return rows.join('')||'<p class="empty">No policies. Joining without business access is allowed.</p>'}
function policyCreateButton(){return canOperate('policy.put')?'<button type="button" data-new-device-policy>New Policy</button>':''}
function policyImpact(policyIDs){
 const matches=ids=>list(ids).some(id=>policyIDs.includes(id)),devices=list(projection.devices).filter(v=>v.authorized&&matches(v.policy_ids)),invites=list(projection.policy_invites).filter(v=>matches(v.policy_ids));
 return `<section data-policy-impact><h3>Shared change · known references</h3><p>${devices.length} authorized device(s) · ${invites.length} pending invitation(s) on this control. Saving changes the rules for every reference.</p>${devices.map(v=>`<p><a href="/devices/${encodeURIComponent(v.id)}" data-nav>${esc(v.name||v.id)}</a> · ${esc(v.policy_ids.filter(id=>policyIDs.includes(id)).join(', '))}</p>`).join('')}${invites.map(v=>`<p><a href="/devices/invites/${encodeURIComponent(v.id)}" data-nav>${esc(v.device_id)} · invitation ${esc(v.id)}</a> · ${esc(v.policy_ids.filter(id=>policyIDs.includes(id)).join(', '))} · ${v.state==='bound'?'Bound; original enrollment may resume':`Open until ${esc(when(v.expires_at))}`}</p>`).join('')}</section>`;
}
// A detached parent form is disposable browser input, not saved authorization.
let policyParent=null;
function openPolicyDraft(button){
 const form=button.closest('#device-policy-form,#enrollment-form');if(form?.submitting)return;
 if(form)policyParent={url:location.pathname+location.search,form};
 history.pushState({},'',button.hasAttribute('data-copy-policy')?`/policies?copy=${encodeURIComponent(button.dataset.copyPolicy)}`:'/policies?new=1');render();
}
function restorePolicyParent(){
 if(!policyParent)return;
 if(location.pathname+location.search===policyParent.url){const parent=policyParent,placeholder=document.getElementById(parent.form.id);if(placeholder){policyParent=null;placeholder.replaceWith(parent.form)}else{const retained=document.createElement('section');retained.className='card';retained.dataset.unappliedPolicyDraft='';retained.innerHTML='<h2>Unapplied device draft</h2><p>This device can no longer accept this assignment. The unsaved fields remain here for review.</p>';for(const field of parent.form.elements)field.disabled=true;for(const button of parent.form.querySelectorAll('button'))button.hidden=true;retained.append(parent.form);app.append(retained)}}
 else if(location.pathname!=='/policies')policyParent=null;
}
function returnFromPolicy(value,accepted,reviewedTargets){
 if(!policyParent)return false;
 if(value){
  const form=policyParent.form,policies=JSON.parse(form.dataset.policies).filter(p=>p.id!==value.id),targets=JSON.parse(form.dataset.targets),selected=[...form.querySelectorAll('[name=policy_id]:checked')].map(e=>e.value),sameService=policies.filter(p=>p.service_id===value.service_id).map(p=>p.id);
  policies.push(value);policies.sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0);
  for(const [kind,id]of [['policy',value.id],['service',value.service_id]]){const target=list(kind==='policy'?accepted.snapshot.targets:reviewedTargets).find(t=>t.target_kind===kind&&t.target_id===id);if(!target||target.deleted||target.conflicted||kind==='policy'&&(target.material_ids.length!==1||target.material_ids[0]!==accepted.material_id))throw Error('Policy saved, but its current rules are unavailable or changed. Review it before assigning.');const index=targets.findIndex(t=>t.target_kind===kind&&t.target_id===id);if(index<0)targets.push(target);else targets[index]=target}
  form.dataset.policies=JSON.stringify(policies);form.dataset.targets=JSON.stringify(targets);
  form.querySelector('[data-policy-choices]').innerHTML=policyChoices([...selected.filter(id=>!sameService.includes(id)),value.id],policies);
  const access=!!form.querySelector('[name=responsibility][value=access]:checked');for(const choice of form.querySelectorAll('[name=policy_id]'))choice.disabled=!access;
  form.querySelector('[role=alert]').textContent='Policy saved. Review and submit this device assignment separately.';
 }
 history.pushState({},'',policyParent.url);render();return true;
}

