  const pathRows=paths.map(v=>`<tr><td>${esc(v.candidate_id)}</td><td class="mono">${esc(pathLabel(v))}</td><td>${v.selected?'<span class="ok">signed selector</span>':'—'}</td><td>${badge(v.availability)}</td></tr>`).join('');
  const linkRows=list(report?.links).map(v=>`<tr><td class="mono">${esc(v.interface)}</td><td>${esc(v.peer)}</td><td>${badge(v.result)}</td><td>${v.latency_ms?`${esc(v.latency_ms)} ms`:'—'}</td><td>${byteSize(v.rx_bytes)}</td><td>${byteSize(v.tx_bytes)}</td></tr>`).join('');
