function eventsPage(){
  const all=list(projection.events).slice().reverse(),params=new URLSearchParams(location.search),filter=params.get('kind')||'',level=params.get('level')||'',node=params.get('node')||'',search=(params.get('q')||'').toLowerCase(),isProblem=v=>v.level==='problem';
  const events=all.filter(v=>(!filter||v.kind===filter)&&(!level||v.level===level)&&(!node||v.subject===node)&&(!search||`${v.kind} ${v.subject} ${v.from||''} ${v.to||''} ${v.detail}`.toLowerCase().includes(search))),unresolved=all.filter(v=>v.current&&isProblem(v)).length;
  const kinds=[...new Set(all.map(v=>v.kind).filter(Boolean))].sort(),nodes=[...new Set(all.map(v=>v.subject).filter(Boolean))].sort();
  const rows=events.map(v=>`<tr data-event-id="${esc(v.id)}"><td class="mono">${esc(when(v.at))}</td><td>${esc(v.subject)}</td><td><b>${esc(v.kind)}</b><small>${esc(v.detail)}</small></td><td class="mono">${esc(v.from||'—')} → ${esc(v.to||'—')}</td><td><span class="event-dot ${esc(v.level||'information')}"></span>${esc(v.level||'information')}${v.current?'<small>current</small>':''}</td></tr>`).join('');
  app.className='network-page page-events';
  app.innerHTML=`<div class="heading network-heading"><div><span class="eyebrow">OPERATIONS / HISTORY</span><h1>Events</h1><p>Authenticated state transitions and current unresolved observations</p></div><div class="actions"><button type="button" data-refresh-events>Refresh</button><button type="button" data-export-events>Export CSV</button></div></div><div class="overview-health"><span class="status-check ${unresolved?'warn':''}">${unresolved?'!':'✓'}</span><b>${unresolved?`${unresolved} current unresolved issues`:'No current unresolved issues'}</b><span class="dim">History never substitutes for present-state observation.</span></div><div class="steps"><div class="step"><span class="label">CURRENT ISSUES</span><b class="${unresolved?'bad':'ok'}">${unresolved} unresolved</b></div><div class="step"><span class="label">PENDING WINDOWS</span><b>${all.filter(v=>v.kind==='enrollment'&&v.current).length} current</b></div><div class="step"><span class="label">VISIBLE RECORDS</span><b>${events.length} / ${all.length}</b></div><div class="step"><span class="label">RETENTION</span><b>30 days</b><span class="tiny dim">when retained by source</span></div></div><form class="card filter-bar" data-page-filter><label>Search<input type="search" name="q" value="${esc(params.get('q')||'')}" placeholder="Search events…"></label><label>Level<select name="level"><option value="">All levels</option>${['problem','recovery','information','pending'].map(value=>`<option ${value===level?'selected':''}>${value}</option>`).join('')}</select></label><label>Kind<select name="kind"><option value="">All kinds</option>${kinds.map(value=>`<option ${value===filter?'selected':''}>${esc(value)}</option>`).join('')}</select></label><label>Node<select name="node"><option value="">All nodes</option>${nodes.map(value=>`<option ${value===node?'selected':''}>${esc(value)}</option>`).join('')}</select></label><button type="submit">Apply</button><a class="button" href="/events" data-nav>Clear</a></form><div class="events-layout"><section class="card events-table"><div class="sectionhead"><div><h2>State transitions</h2><p class="tiny dim">A quiet system produces no events. Current truth is read independently.</p></div></div>${table(['TIME','NODE','KIND / SUBJECT','CHANGE','SEMANTIC'],rows)}</section><aside class="events-side"><section class="card"><h2>Event semantics</h2><div class="event-semantic"><b><i class="problem"></i>Problem</b><p>Current signed evidence reports a bad state.</p><b><i class="recovery"></i>Recovery</b><p>A previously bad state returned to normal.</p><b><i class="information"></i>Information</b><p>Authority, enrollment, route or deployment changed.</p><b><i class="pending"></i>Pending</b><p>A safe transition is not yet complete.</p></div><p class="tiny dim">Events explain changes; live state remains authoritative.</p></section></aside></div>`
}
function ssotPage(){app.className='network-page page-ssot';app.innerHTML=heading('Settings','Authenticated facts and local write authority.')+`<div class="steps"><div class="step"><span class="label">NETWORK</span><b>${esc(projection.network_id)}</b></div><div class="step"><span class="label">MEMBER CONFIG</span><b>${esc(short(projection.control_config_id))}</b></div><div class="step"><span class="label">LOCAL WRITES</span><b>${projection.ui_state.writable?'Available':'Read only'}</b></div></div><section class="card"><h2>Signed fact frontier</h2>${table(['KEY','SEQUENCE','TIP'],list(projection.fact_frontier).map(v=>`<tr><td class="mono">${esc(short(v.key_id))}</td><td>${esc(v.sequence)}</td><td class="mono">${esc(short(v.tip_material_id))}</td></tr>`).join(''))}<p>Each operation references the facts reviewed in its form. Local acceptance does not claim propagation to every device.</p><a class="button" href="/services" data-nav>Services</a><a class="button" href="/policies" data-nav>Policies</a></section><section class="card" id="administrators"><h2>Administrators</h2><p>Each certificate grants full management access. Removing it takes effect on controls that have received the change.</p>${table(['CERTIFICATE','FINGERPRINT','VALID UNTIL',''],list(projection.administrators).map(v=>`<tr data-key="${esc(v.id)}"><td>${esc(v.subject||v.id)}<small class="mono">${esc(v.id)}</small></td><td class="mono">${esc(v.fingerprint)}</td><td>${esc(when(v.not_after))}</td><td>${canOperate('admin_certificate.delete')?`<button class="danger" type="button" data-delete-kind="admin_certificate" data-delete-id="${esc(v.id)}" ${draftAttributes()}>Revoke</button>`:''}</td></tr>`).join(''))}${canOperate('admin_certificate.put')?`<form id="admin-certificate-form" ${draftAttributes()}><div class="field"><label>Public administrator file</label><input type="file" name="certificate" accept="application/json,.json" required><small>Select admin.json from the control's delivery directory. Keep the P12, password and private key on your device.</small></div><div class="service-save"><span role="alert"></span><button class="primary" type="submit">Grant administrator access</button></div></form>`:''}</section>`}
