document.addEventListener('submit',async event=>{
 if(event.target.matches('[data-page-filter]')){event.preventDefault();const query=new URLSearchParams(new FormData(event.target));for(const [key,value]of [...query])if(!value)query.delete(key);history.pushState({},'',`${location.pathname}${query.size?'?'+query:''}`);render();return}
 const element=event.target;if(!element.matches('#service-form,#policy-form,#device-policy-form,#expected-component-form,#enrollment-form,#admin-certificate-form'))return;
 event.preventDefault();if(element.submitting)return;element.submitting=true;const form=new FormData(element),output=element.querySelector('[role=alert]'),ids=name=>String(form.get(name)||'').split(',').map(v=>v.trim()).filter(Boolean).sort();output.textContent='Submitting…';
 try{
  let operation,payload,dependencies;
  if(element.getAttribute('id')==='admin-certificate-form'){
   const file=form.get('certificate');if(!(file instanceof File)||!file.size||file.size>65536)throw Error('Select the public admin.json file.');
   const raw=await file.text();payload=JSON.parse(raw);if(canonical(payload)!==raw||Object.keys(payload).sort().join(',')!=='certificate_der,id'||typeof payload.id!=='string'||typeof payload.certificate_der!=='string')throw Error('Select the original canonical public admin.json file.');
   operation='admin_certificate.put';dependencies=commandDependencies(element,'admin_certificate',payload.id);
  }else if(element.getAttribute('id')==='service-form'){
   operation='service.put';payload={id:String(form.get('id')),name:String(form.get('name')),kind:'internet',matchers:parseMatchers(form.get('matchers'))};dependencies=commandDependencies(element,'service',payload.id);
  }else if(element.getAttribute('id')==='policy-form'){
   const scope=name=>{const mode=String(form.get(name+'_mode'));return {mode,node_ids:mode==='only'?ids(name+'_ids'):[]}};
   operation='policy.put';payload={id:String(form.get('id')),name:String(form.get('name')),service_id:element.elements.namedItem('service_id').value,action:String(form.get('action')),entry_scope:scope('entry_scope'),relay_scope:scope('relay_scope'),exit_scope:scope('exit_scope'),allow_direct:form.has('allow_direct'),local_egress_devices:ids('local_egress_devices')};
   if(element.dataset.creating==='true'&&JSON.parse(element.dataset.targets).some(t=>t.target_kind==='policy'&&t.target_id===payload.id))throw Error('A new Policy needs an unused ID. The existing Policy was not changed.');
   const maxHops=String(form.get('max_hops')||'').trim();if(maxHops){if(!/^[1-9][0-9]*$/.test(maxHops)||!Number.isSafeInteger(Number(maxHops)))throw new Error('Maximum managed nodes must be a positive integer.');payload.max_hops=Number(maxHops);}
   dependencies=commandDependencies(element,'policy',payload.id,[],payload.service_id,[...payload.entry_scope.node_ids,...payload.relay_scope.node_ids,...payload.exit_scope.node_ids,...payload.local_egress_devices]);
  }else if(element.getAttribute('id')==='expected-component-form'){
   operation='expected_component.put';payload=JSON.parse(String(form.get('component')));payload.id=await expectedComponentID(payload);dependencies=commandDependencies(element,'expected_component',payload.id,[],undefined,[payload.node_id]);
  }else if(element.getAttribute('id')==='device-policy-form'){
   operation='device.put';payload={id:element.dataset.deviceId,name:String(form.get('name')),responsibilities:form.getAll('responsibility').map(String).sort(),policy_ids:form.getAll('policy_id').map(String).sort(),distribution_urls:String(form.get('distribution_urls')).split('\n').map(v=>v.trim()).filter(Boolean).sort()};const dns=String(form.get('dns_servers')||'').split('\n').map(v=>v.trim()).filter(Boolean).sort();if(dns.length)payload.dns_servers=dns;dependencies=commandDependencies(element,'device',payload.id,payload.policy_ids);
  }else{
   const options=JSON.parse(element.dataset.options),endpoint=options.endpoints[Number(form.get('endpoint'))];if(!endpoint)throw Error('No authenticated serving endpoint is available.');
   operation='invite.issue';payload={id:element.dataset.transactionId,genesis_digest:options.genesis_digest,issuer_control_id:options.issuer_control_id,device_id:String(form.get('device_id')),name:String(form.get('name')),responsibilities:form.getAll('responsibility').map(String).sort(),policy_ids:form.getAll('policy_id').map(String).sort(),medium:String(form.get('medium')),endpoint};const dns=String(form.get('dns_servers')||'').split('\n').map(v=>v.trim()).filter(Boolean).sort();if(dns.length)payload.dns_servers=dns;
   if(payload.medium==='ssh'){payload.ssh_target=String(form.get('ssh_target')||'');const checked=element.sshCheck;if(!checked||checked.key!==canonical(sshDraft(element)))throw Error('Check the selected SSH target and responsibilities first.');if(checked.result.installation.identity)throw Error('Manage the existing device or continue its original invitation.');if(!checked.result.installation.can_install)throw Error('The target installation conditions have not passed.');}
   dependencies=commandDependencies(element,'invite',payload.id,payload.policy_ids);dependencies.push(...targetDependencies(JSON.parse(element.dataset.targets),'endpoint',endpoint.id,true));
  }
  // Keep the exact submitted bytes with this disposable draft. A new edit
  // gets a new request ID, while its reviewed object/dependency IDs stay put.
  const draft=canonical({operation,payload,dependencies:[...new Set(dependencies)].sort()});
  if(!element.submission||element.submission.draft!==draft){
   if(element.submission)element.dataset.requestId=crypto.randomUUID();
   if(operation==='invite.issue')payload.expires_at=Date.now()+15*60*1000;
   element.submission={draft,body:operationBody(operation,payload,element.dataset.requestId,dependencies)};
  }
  const accepted=await submitOperation(operation,element.submission.body);
  if(operation==='policy.put'){if(returnFromPolicy(payload,accepted,JSON.parse(element.dataset.targets))){toast('Policy saved. Device assignment is still a draft.');return}history.pushState({},'',`/policies?policy=${encodeURIComponent(payload.id)}`)}
  if(operation==='invite.issue')history.pushState({},'',`/devices/invites/${encodeURIComponent(payload.id)}`);
  render();
  if(operation==='invite.issue'&&payload.medium==='ssh'){try{await startSSH(payload.id);inviteCache.delete(payload.id);stableRender();toast('Invitation accepted. SSH execution started.')}catch(error){toast('Invitation accepted; SSH execution not confirmed: '+error.message,true)}}else toast('Accepted locally. Device propagation is separate.');
 }catch(error){output.textContent=error.message}finally{element.submitting=false}
});
let reconnectDelay=1000;
function connectLive(){const scheme=location.protocol==='https:'?'wss:':'ws:',socket=new WebSocket(`${scheme}//${location.host}/api/control/ui/live`);socket.onopen=()=>{reconnectDelay=1000;connection.className='ok'};socket.onmessage=event=>{const payload=JSON.parse(event.data),encoded=JSON.stringify(payload);if(encoded!==lastSnapshot){lastSnapshot=encoded;const editing=document.activeElement&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);accept(payload,!editing)}};socket.onclose=()=>{connection.textContent='Reconnecting…';connection.className='bad';const delay=reconnectDelay;reconnectDelay=Math.min(30000,reconnectDelay*2);setTimeout(connectLive,delay)};socket.onerror=()=>socket.close()}
